<div class="status-tabs"><?php foreach (['' => __('Tutti')] + array_map('__', Alien\Services\Orders::STATUSES) as $k => $l): $n = $k === '' ? $counts['all'] : ($counts[$k] ?? 0); ?><a class="<?= ($_GET['status'] ?? '') === $k ? 'on' : '' ?>" href="<?= e(url('admin/orders' . ($k !== '' ? '?status=' . $k : ''))) ?>"><?= e($l) ?><b><?= $n ?></b></a><?php endforeach ?></div>
<div class="toolbar"><form method="get" action="<?= e(url('admin/orders')) ?>"><input type="search" name="q" placeholder="<?= e(__('Numero o email')) ?>" value="<?= e($_GET['q'] ?? '') ?>">
<select name="status"><option value=""><?= e(__('Tutti gli stati')) ?></option><?php foreach (Alien\Services\Orders::STATUSES as $k => $l): ?><option value="<?= $k ?>" <?= ($_GET['status'] ?? '') === $k ? 'selected' : '' ?>><?= e(__($l)) ?></option><?php endforeach ?></select>
<button class="btn sec" type="submit"><?= e(__('Filtra')) ?></button></form></div>
<div class="card" style="padding:0"><table><thead><tr><th><?= e(__('Ordine')) ?></th><th><?= e(__('Data')) ?></th><th><?= e(__('Cliente')) ?></th><th><?= e(__('Stato')) ?></th><th><?= e(__('Pagamento')) ?></th><th class="right"><?= e(__('Totale')) ?></th></tr></thead><tbody>
<?php foreach ($orders as $o): ?><tr><td><a href="<?= e(url('admin/orders/' . $o['id'])) ?>"><strong><?= e($o['number']) ?></strong></a></td><td class="nowrap"><?= e(a_dt($o['created_at'])) ?></td><td><?= e($o['email']) ?></td><td><?= a_status($o['status']) ?></td><td><?= a_status($o['payment_status']) ?> <span class="muted"><?= e($o['payment_method']) ?></span></td><td class="right"><?= e(Alien\Core\Money::format((int)$o['total'], $o['currency'])) ?></td></tr><?php endforeach ?>
<?php if (!$orders): ?><tr><td colspan="6"><?= a_empty('🛍️', __('Nessun ordine qui'), __('Gli ordini dei clienti appariranno in questa lista.')) ?></td></tr><?php endif ?></tbody></table></div>
<?php if ($pg['pages'] > 1): $qs = $_GET; ?><div class="pager"><?php for ($i = 1; $i <= $pg['pages']; $i++): $qs['page'] = $i; ?><?= $i === $pg['page'] ? '<span class="cur">' . $i . '</span>' : '<a href="' . e(url('admin/orders?' . http_build_query($qs))) . '">' . $i . '</a>' ?><?php endfor ?></div><?php endif ?>
